const linked=/^<!-- forge:linked-task:([a-z0-9-]+):start -->\r?\n[\s\S]*?^<!-- forge:linked-task:\1:end -->\r?\n/gm;
const normalize=text=>String(text).replace(/version=\d+\.\d+\.\d+/g,'version=<dynamic>');
const read=file=>fs.readFileSync(path.join(ROOT,file)),attrHash=bytes=>hash(bytes.toString('utf8').replace(linked,''));
const decode=row=>zlib.gunzipSync(Buffer.from(row.before_gzip_base64,'base64'),{maxOutputLength:4*1024*1024});
function rowFor(file,value=layer){return value.files[file]||(file===value.control_doc.file?value.control_doc:null);}
function predecessorRead(readRaw,file,value=layer){
 const row=rowFor(file,value);if(!row||row.before===null)return readRaw(file);
 const bytes=decode(row);assert.equal(hash(bytes),SPEC.files[file]?.before||SPEC.control_doc.before,'#343 exact prior source '+file);return bytes;
}
const artifactKey=item=>item.source_id+'::'+item.source;
function predecessorArtifacts(artifacts,value=layer){
 return artifacts.map(item=>{const row=value.rendered[artifactKey(item)];if(!row)return item;
  const content=decode(row).toString('utf8');assert.equal(hash(normalize(content)),SPEC.rendered[artifactKey(item)].before);
  return {...item,content,...(Object.hasOwn(item,'bytes')?{bytes:Buffer.byteLength(content)}:{})};});
}
function measure(artifacts,id,attributed=false){return hash(artifacts.filter(item=>item.source_id===id).sort((a,b)=>a.source.localeCompare(b.source))
 .map(item=>item.source+'\0'+normalize(attributed?item.content.replace(linked,''):item.content)).join('\0'));}
function validateOwn({artifacts,readRaw,value}){
 assert.deepEqual(Object.keys(value).sort(),['schema_version','issue','kind','provenance','files','rendered','surfaces','unchanged_surfaces','samples','control_doc'].sort(),'#343 closed next layer');
 assert.equal(value.schema_version,1);assert.equal(value.issue,343);assert.equal(value.kind,'parallelism-measured-next-terminal');
 assert.deepEqual(value.provenance,SPEC.provenance,'#343 exact source provenance');
 for(const section of ['files','rendered','surfaces'])assert.deepEqual(Object.keys(value[section]),Object.keys(SPEC[section]),'#343 exact '+section);
 assert.deepEqual(value.unchanged_surfaces,SPEC.unchanged_surfaces);assert.deepEqual(artifacts.map(artifactKey).sort(),SPEC.members);
 for(const[file,pin]of Object.entries(SPEC.prior_pins))assert.equal(hash(readRaw(file)),pin,'#343 immutable prior fixture '+file);
 for(const[file,expected]of Object.entries(SPEC.files)){
  const row=value.files[file];assert.deepEqual(Object.keys(row).sort(),['before','after','attributed_before','attributed_after','before_gzip_base64'].sort());
  for(const field of ['before','after','attributed_before','attributed_after'])assert.equal(row[field],expected[field],'#343 independent '+field+' '+file);
  const actual=readRaw(file);
  if(file==='scripts/forge-smoke.js'&&hash(actual)!==expected.after){
   const text=actual.toString('utf8'),a=text.indexOf('// ── Section 8:'),b=text.indexOf('// ── Section 9:',a);
   const outside=a>=0&&b>a&&hash(text.slice(a,b))===SPEC.smoke_section_after;
   throw Object.assign(new assert.AssertionError({message:outside?'unrecognized smoke changes outside Section8: #343 exact scope':'unrecognized smoke changes: independent Section8 after: #343 exact scope'}),{parallelismSmokeDrift:true});
  }
  assert.equal(hash(actual),expected.after,'#343 measured source '+file);assert.equal(attrHash(actual),expected.attributed_after);
  if(expected.before===null)assert.equal(row.before_gzip_base64,null);
  else{const bytes=decode(row);assert.equal(hash(bytes),expected.before);assert.equal(attrHash(bytes),expected.attributed_before);}
 }
 for(const[key,expected]of Object.entries(SPEC.rendered)){
  const row=value.rendered[key],item=artifacts.find(item=>artifactKey(item)===key);
  assert.deepEqual(Object.keys(row).sort(),['source_id','source','before','after','attributed_before','attributed_after','before_gzip_base64'].sort());
  for(const field of ['source_id','source','before','after','attributed_before','attributed_after'])assert.equal(row[field],expected[field],'#343 independent rendered '+field);
  assert.equal(hash(normalize(item.content)),expected.after);assert.equal(hash(normalize(item.content.replace(linked,''))),expected.attributed_after);
  assert.equal(hash(normalize(decode(row).toString('utf8'))),expected.before);
 }
 for(const[id,expected]of Object.entries(SPEC.surfaces)){assert.deepEqual(value.surfaces[id],expected);assert.equal(measure(artifacts,id),expected.after);assert.equal(measure(artifacts,id,true),expected.attributed_after);}
 for(const[id,pin]of Object.entries(SPEC.unchanged_pins)){assert.equal(measure(artifacts,id),pin.before);assert.equal(measure(artifacts,id,true),pin.attributed_before);}
 assert.deepEqual(value.samples,SPEC.samples,'#343 two real citation spans');
 const text=readRaw(value.samples.file).toString('utf8'),prior=predecessorRead(readRaw,value.samples.file,value).toString('utf8');
 for(const row of value.samples.nodes)assert.equal(row.pointer.split('/').slice(1).reduce((v,key)=>v[key],JSON.parse(text)),row.after);
 const oldHash=value.samples.nodes[0].before,newHash=value.samples.nodes[0].after;assert(value.samples.nodes.every(row=>row.before===oldHash&&row.after===newHash));
 assert.equal(text.split(newHash).length,3);assert.equal(text.split(newHash).join(oldHash),prior,'#343 all noncitation sample bytes retained');
 assert.deepEqual(Object.keys(value.control_doc).sort(),['file','before','after','before_gzip_base64'].sort());
 for(const field of ['file','before','after'])assert.equal(value.control_doc[field],SPEC.control_doc[field]);
 assert.equal(hash(readRaw(value.control_doc.file)),SPEC.control_doc.after);assert.equal(hash(decode(value.control_doc)),SPEC.control_doc.before);
 const doc=readRaw(value.control_doc.file).toString('utf8');for(const pins of Object.values(SPEC.surfaces))for(const field of ['before','after','attributed_before','attributed_after'])assert(doc.includes(pins[field]));
 return true;
}
function validate(options){
 const {artifacts,readRaw=read,parallelismLayerValue=layer,...rest}=options;
 // Inherited metadata is rejected by its original error contract. The prior
 // bytes are real frozen inputs. Success ALSO requires every actual byte below.
 let inheritedError;
 try{previous.validate({...rest,artifacts:predecessorArtifacts(artifacts,parallelismLayerValue),readRaw:file=>predecessorRead(readRaw,file,parallelismLayerValue)});}catch(error){inheritedError=error;}
 try{validateOwn({artifacts,readRaw,value:parallelismLayerValue});}
 catch(error){if(error.parallelismSmokeDrift)throw error;if(inheritedError)throw inheritedError;throw error;}
 if(inheritedError)throw inheritedError;
 return true;
}
function after(kind,key,prior,attributed=false){
 const before=previous.after(kind,key,prior,attributed),row=kind==='surfaces'?SPEC.surfaces[key]:SPEC.files[key];if(!row)return before;
 assert.equal(before,row[attributed?'attributed_before':'before'],'#343 chained prior '+key);return row[attributed?'attributed_after':'after'];
}
function sampleAfter(pointer,prior){
 const before=previous.sampleAfter(pointer,prior),row=SPEC.samples.nodes.find(n=>n.pointer===pointer||n.pointer===pointer+'/source/sha256');if(!row)return before;
 assert.equal(before,row.before,'#343 exact chained sample prior '+pointer);return row.after;
}
function projectGolden(golden){const prior=previous.projectGolden(golden);return {...prior,surfaces:prior.surfaces.map(row=>{const pins=SPEC.surfaces[row.source_id];if(!pins)return row;assert.equal(row.sha256,pins.before,'#343 golden prior');return {...row,sha256:pins.after};})};}
function previousSamples(text){assert.equal(hash(text),SPEC.files[SPEC.samples.file].after,'#343 exact sample bytes before historical projection');return previous.previousSamples(predecessorRead(()=>Buffer.from(text),SPEC.samples.file).toString('utf8'));}
function previousSmoke(text){
 const row=SPEC.files['scripts/forge-smoke.js'];if(!row)return previous.previousSmoke(text);
 if(hash(text)!==row.after)throw new assert.AssertionError({message:'unrecognized smoke changes: outside the exact343 measured source'});
 return previous.previousSmoke(predecessorRead(()=>Buffer.from(text),'scripts/forge-smoke.js').toString('utf8'));
}
module.exports={...previous,parallelismLayer:layer,parallelismSources:Object.keys(SPEC.files),validate,after,sampleAfter,projectGolden,previousSamples,previousSmoke};
